USE aiims_connect;
CREATE OR REPLACE VIEW Patient_Self_View AS SELECT p.UHID,p.Name,p.DOB,a.Appt_ID,a.Appt_Date,a.Time_Slot,a.Status Appointment_Status,b.Branch_Name FROM patient p LEFT JOIN appointment a ON p.UHID=a.UHID LEFT JOIN branch b ON b.Branch_ID=a.Branch_ID;
CREATE OR REPLACE VIEW Doctor_Schedule_View AS SELECT a.Appt_ID,a.Appt_Date,a.Time_Slot,a.Token_No,a.Status,p.UHID,p.Name Patient_Name,s.Name Doctor_Name,b.Branch_Name FROM appointment a JOIN patient p ON p.UHID=a.UHID JOIN staff s ON s.Staff_ID=a.Staff_ID JOIN branch b ON b.Branch_ID=a.Branch_ID;
CREATE OR REPLACE VIEW Branch_Ward_View AS SELECT b.Branch_ID,b.Branch_Name,w.Ward_ID,w.Ward_Name,w.Ward_Type,w.Total_Beds,w.Available_Beds,w.Total_Beds-w.Available_Beds Occupied_Beds FROM branch b JOIN ward w ON w.Branch_ID=b.Branch_ID;
CREATE OR REPLACE VIEW Chain_Occupancy_View AS SELECT b.Branch_ID,b.Branch_Name,COALESCE(SUM(w.Total_Beds),0) Total_Beds,COALESCE(SUM(w.Available_Beds),0) Available_Beds,COALESCE(SUM(w.Total_Beds-w.Available_Beds),0) Occupied_Beds FROM branch b LEFT JOIN ward w ON w.Branch_ID=b.Branch_ID GROUP BY b.Branch_ID,b.Branch_Name;
CREATE OR REPLACE VIEW Referral_Flow_View AS SELECT f.Branch_Name From_Branch,t.Branch_Name To_Branch,r.Status,COUNT(*) Referral_Count FROM referral r JOIN branch f ON f.Branch_ID=r.From_Branch_ID JOIN branch t ON t.Branch_ID=r.To_Branch_ID GROUP BY f.Branch_Name,t.Branch_Name,r.Status;
CREATE OR REPLACE VIEW Branch_Revenue_View AS SELECT b.Branch_ID,b.Branch_Name,COALESCE(SUM(bi.Total),0) Revenue FROM branch b LEFT JOIN ward w ON w.Branch_ID=b.Branch_ID LEFT JOIN admission a ON a.Ward_ID=w.Ward_ID LEFT JOIN billing bi ON bi.Admission_ID=a.Admission_ID GROUP BY b.Branch_ID,b.Branch_Name;
CREATE OR REPLACE VIEW Patient_History_View AS SELECT p.UHID,p.Name Patient_Name,b.Branch_Name,a.Appt_Date,pr.Medicine_Name,pr.Dosage FROM patient p LEFT JOIN appointment a ON a.UHID=p.UHID LEFT JOIN branch b ON b.Branch_ID=a.Branch_ID LEFT JOIN prescription pr ON pr.Appt_ID=a.Appt_ID;
